// this file is generated by ai
import React, { useState, useEffect, useRef } from 'react';
import DeckGL from '@deck.gl/react';
import { ScatterplotLayer, PathLayer, LineLayer, TextLayer, BitmapLayer } from '@deck.gl/layers';
import { TileLayer } from '@deck.gl/geo-layers';

const WS_URL = 'ws://localhost:8080';

// Reference antenna origin (matches .env)
const ANTENNA_ORIGIN = {
  longitude: Number(import.meta.env.REF_LON) || 0.0,
  latitude: Number(import.meta.env.REF_LAT) || 0.0,
  altitude: Number(import.meta.env.REF_ALT_M) || 0.0
};

const INITIAL_VIEW_STATE = {
  longitude: ANTENNA_ORIGIN.longitude,
  latitude: ANTENNA_ORIGIN.latitude,
  zoom: 10,
  pitch: 50,
  bearing: 0
};

const renderBitmapTile = props => {
  const { boundingBox } = props.tile;
  return new BitmapLayer(props, {
    data: null,
    image: props.data,
    bounds: [boundingBox[0][0], boundingBox[0][1], boundingBox[1][0], boundingBox[1][1]]
  });
};

export default function App() {
  const [isDarkMode, setIsDarkMode] = useState(true);
  const [aircraftList, setAircraftList] = useState([]);
  const [wsConnected, setWsConnected] = useState(false);

  // Persistent Map (Key: hex -> Value: aircraft state + 3D trajectory arrays)
  const aircraftMapRef = useRef(new Map());

  useEffect(() => {
    let ws;
    let reconnectTimer;

    function connect() {
      ws = new WebSocket(WS_URL);

      ws.onopen = () => {
        console.log('[Deck.gl UI] Connected to WebSocket bridge');
        setWsConnected(true);
      };

      ws.onmessage = (event) => {
        try {
          const ping = JSON.parse(event.data);
          const map = aircraftMapRef.current;
          const prev = map.get(ping.hex);

          const filtCoord = [ping.filtered_lon, ping.filtered_lat, ping.filtered_alt_m];
          const rawCoord = [ping.raw_lon, ping.raw_lat, ping.raw_alt_m];

          // Keep up to the last 200 points of trajectory history per aircraft
          const filteredPath = prev ? [...prev.filteredPath.slice(-200), filtCoord] : [filtCoord];
          const rawPath = prev ? [...prev.rawPath.slice(-200), rawCoord] : [rawCoord];

          map.set(ping.hex, {
            ...ping,
            lastSeenMs: Date.now(),
            filteredPath,
            rawPath
          });
        } catch (err) {
          console.error('Failed to parse telemetry JSON:', err);
        }
      };

      ws.onclose = () => {
        setWsConnected(false);
        reconnectTimer = setTimeout(connect, 2000);
      };
    }

    connect();

    // Refresh React UI state at 15 FPS & prune aircraft unseen for > 60s
    const uiInterval = setInterval(() => {
      const now = Date.now();
      const map = aircraftMapRef.current;
      for (const [hex, ac] of map.entries()) {
        if (now - ac.lastSeenMs > 60000) {
          map.delete(hex);
        }
      }
      setAircraftList(Array.from(map.values()));
    }, 66);

    return () => {
      clearInterval(uiInterval);
      clearTimeout(reconnectTimer);
      if (ws) ws.close();
    };
  }, []);

  // Filter subset of aircraft currently experiencing an anomaly / spoofing attack
  const anomalousAircraft = aircraftList.filter(d => d.is_anomalous);

  const layers = [
    // 1A. Base Map Layer (Dark Esri vs Light OSM)
    new TileLayer({
      id: isDarkMode ? 'dark-base-map' : 'light-base-map',
      data: isDarkMode
        ? 'https://server.arcgisonline.com/ArcGIS/rest/services/Canvas/World_Dark_Gray_Base/MapServer/tile/{z}/{y}/{x}'
        : 'https://tile.openstreetmap.org/{z}/{x}/{y}.png',
      minZoom: 0,
      maxZoom: isDarkMode ? 16 : 19,
      tileSize: 256,
      renderSubLayers: renderBitmapTile
    }),

    // 1B. Dark Labels Overlay
    isDarkMode && new TileLayer({
      id: 'dark-base-labels',
      data: 'https://server.arcgisonline.com/ArcGIS/rest/services/Canvas/World_Dark_Gray_Reference/MapServer/tile/{z}/{y}/{x}',
      minZoom: 0,
      maxZoom: 16,
      tileSize: 256,
      renderSubLayers: renderBitmapTile
    }),

    // 2. Reference Antenna Origin Marker
    new ScatterplotLayer({
      id: 'antenna-origin-layer',
      data: [ANTENNA_ORIGIN],
      getPosition: d => [d.longitude, d.latitude, d.altitude],
      getFillColor: [0, 220, 255, 220],
      getRadius: 250,
      radiusMinPixels: 5
    }),

    // 3. Kalman Uncertainty Radius Halo (grows when coasting through spoofing!)
    new ScatterplotLayer({
      id: 'uncertainty-halo-layer',
      data: aircraftList,
      getPosition: d => [d.filtered_lon, d.filtered_lat, d.filtered_alt_m],
      getRadius: d => d.uncertainty_m,
      getFillColor: d => d.is_anomalous ? [255, 165, 0, 50] : [0, 255, 170, 35],
      getLineColor: d => d.is_anomalous ? [255, 165, 0, 180] : [0, 255, 170, 120],
      stroked: true,
      lineWidthMinPixels: 1
    }),

    // 4. Kalman Filtered 3D Flight Path (Smooth Trajectory)
    new PathLayer({
      id: 'filtered-trajectory-layer',
      data: aircraftList,
      getPath: d => d.filteredPath,
      getColor: d => d.is_anomalous ? [255, 200, 0, 230] : [0, 255, 170, 210],
      getWidth: 4,
      widthMinPixels: 2
    }),

    // 5. Spoofing Displacement Vector (Line from Filtered Pos -> Rejected Spoof Pos)
    new LineLayer({
      id: 'spoof-vector-layer',
      data: anomalousAircraft,
      getSourcePosition: d => [d.filtered_lon, d.filtered_lat, d.filtered_alt_m],
      getTargetPosition: d => [d.raw_lon, d.raw_lat, d.raw_alt_m],
      getColor: [255, 40, 60, 230],
      getWidth: 3,
      widthMinPixels: 2
    }),

    // 6. Rejected Raw Spoofed GPS Position (Red Phantom Dot)
    new ScatterplotLayer({
      id: 'raw-spoof-pos-layer',
      data: anomalousAircraft,
      getPosition: d => [d.raw_lon, d.raw_lat, d.raw_alt_m],
      getFillColor: [255, 20, 40, 240],
      getRadius: 200,
      radiusMinPixels: 6
    }),

    // 7. Kalman Filtered Aircraft Position Dot
    new ScatterplotLayer({
      id: 'filtered-aircraft-dot',
      data: aircraftList,
      getPosition: d => [d.filtered_lon, d.filtered_lat, d.filtered_alt_m],
      getFillColor: d => d.is_anomalous ? [255, 180, 0, 255] : [0, 255, 170, 255],
      getRadius: 120,
      radiusMinPixels: 5,
      pickable: true
    }),

    // 8. Aircraft Callsign & Spoof Alert Labels
    new TextLayer({
      id: 'aircraft-labels',
      data: aircraftList,
      getPosition: d => [d.filtered_lon, d.filtered_lat, d.filtered_alt_m + 150],
      getText: d => {
        const name = d.callsign && d.callsign !== 'N/A' ? d.callsign.trim() : d.hex;
        return d.is_anomalous ? `⚠️ ${name} [SPOOF REJECTED]` : name;
      },
      getSize: 13,
      getColor: d => d.is_anomalous ? [255, 80, 80, 255] : (isDarkMode ? [230, 240, 255, 230] : [15, 23, 42, 240]),
      getTextAnchor: 'middle',
      getAlignmentBaseline: 'bottom'
    })
  ];

  return (
    <div style={{
      width: '100vw',
      height: '100vh',
      position: 'relative',
      overflow: 'hidden',
      background: isDarkMode ? '#0b0f19' : '#e5e3df',
      fontFamily: 'system-ui, sans-serif'
    }}>
      <DeckGL
        initialViewState={INITIAL_VIEW_STATE}
        controller={true}
        layers={layers}
        getTooltip={({ object }) => object && object.hex && (
          `ICAO: ${object.hex} (${object.callsign})\n` +
          `Alt: ${Math.round(object.filtered_alt_m)}m\n` +
          `Uncertainty: ±${object.uncertainty_m.toFixed(1)}m\n` +
          `Mahalanobis d²: ${object.mahalanobis_d2.toFixed(1)}\n` +
          `Status: ${object.is_anomalous ? '🚨 ' + object.anomaly_reason : '✅ NORMAL'}`
        )}
      />

      {/* Top-Left Telemetry HUD Panel */}
      <div style={{
        position: 'absolute',
        top: '20px',
        left: '20px',
        zIndex: 10,
        padding: '14px 18px',
        borderRadius: '10px',
        background: isDarkMode ? 'rgba(15, 23, 42, 0.88)' : 'rgba(255, 255, 255, 0.92)',
        color: isDarkMode ? '#f8fafc' : '#0f172a',
        border: isDarkMode ? '1px solid #334155' : '1px solid #cbd5e1',
        boxShadow: '0 4px 12px rgba(0,0,0,0.3)',
        minWidth: '260px'
      }}>
        <div style={{ fontWeight: 'bold', fontSize: '15px', marginBottom: '6px' }}>
          🛡️ ADS-B Kalman Guard
        </div>
        <div style={{ fontSize: '13px', opacity: 0.9 }}>
          Bridge: <span style={{ color: wsConnected ? '#10b981' : '#ef4444', fontWeight: 'bold' }}>
            {wsConnected ? '● LIVE' : '○ DISCONNECTED'}
          </span>
        </div>
        <div style={{ fontSize: '13px', opacity: 0.9 }}>
          Tracked Aircraft: <b>{aircraftList.length}</b>
        </div>
        <div style={{ fontSize: '13px', color: anomalousAircraft.length > 0 ? '#ef4444' : 'inherit', fontWeight: anomalousAircraft.length > 0 ? 'bold' : 'normal' }}>
          Active Spoof Alerts: {anomalousAircraft.length}
        </div>
      </div>

      {/* Top-Right Theme Toggle Button */}
      <button
        onClick={() => setIsDarkMode(!isDarkMode)}
        style={{
          position: 'absolute',
          top: '20px',
          right: '20px',
          zIndex: 10,
          padding: '10px 16px',
          borderRadius: '8px',
          border: isDarkMode ? '1px solid #334155' : '1px solid #cbd5e1',
          background: isDarkMode ? 'rgba(15, 23, 42, 0.85)' : 'rgba(255, 255, 255, 0.9)',
          color: isDarkMode ? '#f8fafc' : '#0f172a',
          fontWeight: 'bold',
          cursor: 'pointer',
          boxShadow: '0 4px 12px rgba(0,0,0,0.25)'
        }}
      >
        {isDarkMode ? '☀️ Light Mode' : '🌙 Dark Mode'}
      </button>
    </div>
  );
}